files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  background: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  block-size: 100%;
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  border: 1px solid black;
  padding: 190px 20px 20px;
  color: white;
  font-family: 'Open Sans', sans-serif;
  background-image: url(https://sandbox.practicum-team.ru/tasks/03-design/05-grid/05-minmax-fit-content/example-01/pre/images/choc.webp);
  background-size: cover;
  max-inline-size: 400px;
}

.card__content {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 10px;
}

.card::after {
  content: '';
  position: absolute;
  background-image: linear-gradient( to top, rgb(0 0 0 / 1), rgb(0 0 0 / 0.6) 30%, rgb(0 0 0 / 0) 40%, rgb(0 0 0 / 0) 100% );
  inset-block-start: 0;
  inset-inline-start: 0;
  inline-size: 100%;
  block-size: 100%;
}

.card__title {
  align-self: flex-start;
  margin: 0;
  font-weight: 400;
  font-size: 16px;
}

.card__button {
  border: 1px solid #000;
  padding: 10px 0;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #ffc802;
  inline-size: 100%;
}

.card__button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.card__button:focus-visible {
  outline: 2px solid #000;
  outline-offset: 0;
}
